以下是一个文件处理类。请为它写 pytest 测试，覆盖：写文件、读文件、文件不存在的情况。测试放在 ```python 代码块中。

类:
```python
import json, os

class NoteStore:
    def __init__(self, filepath='notes.json'):
        self.filepath = filepath

    def add(self, title, content):
        notes = self._load()
        notes.append({'title': title, 'content': content})
        self._save(notes)

    def list(self):
        return self._load()

    def delete(self, index):
        notes = self._load()
        if 0 <= index < len(notes):
            notes.pop(index)
            self._save(notes)
            return True
        return False

    def _load(self):
        if os.path.exists(self.filepath):
            return json.loads(open(self.filepath, encoding='utf-8').read())
        return []

    def _save(self, notes):
        json.dump(notes, open(self.filepath, 'w', encoding='utf-8'), ensure_ascii=False)
